#Requires -Version 7.0
[CmdletBinding()]
param(
    [ValidateSet('Status', 'Invoke', 'CompleteTurn')]
    [string]$Command = 'Status',

    [string]$Method,

    [string]$Params,

    [string]$ParamsPath,

    [object]$ParamsObject,

    [string]$Response,

    [string]$ResponsePath,

    [string]$WorkspacePath = $(if ($env:MCP_WORKSPACE_PATH) { $env:MCP_WORKSPACE_PATH } elseif ($env:MCPSERVER_WORKSPACE_PATH) { $env:MCPSERVER_WORKSPACE_PATH } elseif ($env:CODEX_WORKSPACE_PATH) { $env:CODEX_WORKSPACE_PATH } elseif ($env:CODEX_PROJECT_DIR) { $env:CODEX_PROJECT_DIR } else { (Get-Location).ProviderPath }),

    [string]$PluginRoot = $(if ($env:MCP_PLUGIN_ROOT) { $env:MCP_PLUGIN_ROOT } elseif ($env:CODEX_PLUGIN_ROOT) { $env:CODEX_PLUGIN_ROOT } else { $PSScriptRoot }),

    [string]$CacheRoot,

    [string]$BashPath,

    [int]$TimeoutSeconds = 90
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Resolve-FullPath {
    param([Parameter(Mandatory)][string]$Path)

    $resolved = Resolve-Path -LiteralPath $Path -ErrorAction Stop
    return $resolved.ProviderPath
}

function Read-OptionalText {
    param(
        [string]$Inline,
        [bool]$HasInline,
        [string]$Path
    )

    if ($Path) {
        return [System.IO.File]::ReadAllText((Resolve-FullPath $Path))
    }

    if ($HasInline) {
        return $Inline
    }

    if ([Console]::IsInputRedirected) {
        return [Console]::In.ReadToEnd()
    }

    return ''
}

function Resolve-PowerShellExecutable {
    $command = Get-Command pwsh.exe -ErrorAction SilentlyContinue
    if ($command) {
        return $command.Source
    }

    throw 'Unable to find pwsh.exe. Install PowerShell 7 before using the MCP plugin.'
}

function Invoke-PowerShellPluginScript {
    param(
        [Parameter(Mandatory)][string]$ScriptPath,
        [string[]]$Arguments = @(),
        [string]$StandardInput = ''
    )

    $pwsh = Resolve-PowerShellExecutable
    $pluginRootFull = Resolve-FullPath $PluginRoot
    $workspaceFull = Resolve-FullPath $WorkspacePath
    $cacheOverrideFull = if ($CacheRoot) {
        Resolve-FullPath $CacheRoot
    } elseif ($env:MCP_CACHE_DIR_OVERRIDE) {
        Resolve-FullPath $env:MCP_CACHE_DIR_OVERRIDE
    } else {
        $null
    }
    $startInfo = [System.Diagnostics.ProcessStartInfo]::new()
    $startInfo.FileName = $pwsh
    $startInfo.WorkingDirectory = $workspaceFull
    $startInfo.UseShellExecute = $false
    $startInfo.RedirectStandardInput = $true
    $startInfo.RedirectStandardOutput = $true
    $startInfo.RedirectStandardError = $true
    $startInfo.ArgumentList.Add('-NoLogo')
    $startInfo.ArgumentList.Add('-NoProfile')
    $startInfo.ArgumentList.Add('-NonInteractive')
    $startInfo.ArgumentList.Add('-ExecutionPolicy')
    $startInfo.ArgumentList.Add('Bypass')
    $startInfo.ArgumentList.Add('-File')
    $startInfo.ArgumentList.Add($ScriptPath)
    foreach ($argument in $Arguments) {
        $startInfo.ArgumentList.Add($argument)
    }
    $startInfo.Environment['CODEX_PLUGIN_ROOT'] = $pluginRootFull
    $startInfo.Environment['MCP_PLUGIN_ROOT'] = $pluginRootFull
    [void]$startInfo.Environment.Remove('MCP_CACHE_DIR_OVERRIDE')
    [void]$startInfo.Environment.Remove('PLUGIN_ROOT_OVERRIDE')
    if ($cacheOverrideFull) {
        $startInfo.Environment['MCP_CACHE_DIR_OVERRIDE'] = $cacheOverrideFull
    }
    $startInfo.Environment['MCP_WORKSPACE_PATH'] = $workspaceFull
    $startInfo.Environment['MCPSERVER_WORKSPACE_PATH'] = $workspaceFull
    $startInfo.Environment['MCP_WORKSPACE_START_DIR'] = $workspaceFull
    $startInfo.Environment['CODEX_WORKSPACE_PATH'] = $workspaceFull
    $startInfo.Environment['MCP_PLUGIN_HOST'] = 'codex'
    $startInfo.Environment['PLUGIN_AGENT_DEFAULT'] = 'Codex'
    $startInfo.Environment['PLUGIN_MODEL_DEFAULT'] = 'codex'
    $startInfo.Environment['PLUGIN_TAG'] = 'codex'
    $startInfo.Environment['MCP_AGENT_NAME'] = 'Codex'
    $startInfo.Environment['MCP_AGENT_ID'] = 'Codex'
    $startInfo.Environment['MCP_SESSION_AGENT'] = 'Codex'
    $startInfo.Environment['MCP_SESSION_MODEL'] = 'codex'
    $startInfo.Environment['CT2R_SOURCE_TYPE'] = 'Codex'
    $startInfo.Environment['CT2R_MODEL'] = 'codex'

    $process = [System.Diagnostics.Process]::new()
    $process.StartInfo = $startInfo
    [void]$process.Start()

    if ($StandardInput.Length -gt 0) {
        $process.StandardInput.Write($StandardInput)
    }
    $process.StandardInput.Close()

    $stdoutTask = $process.StandardOutput.ReadToEndAsync()
    $stderrTask = $process.StandardError.ReadToEndAsync()
    $boundedTimeout = [Math]::Max(1, $TimeoutSeconds)
    if (-not $process.WaitForExit($boundedTimeout * 1000)) {
        try {
            if ([System.Environment]::OSVersion.Platform -eq [System.PlatformID]::Win32NT) {
                & "$env:WINDIR\System32\taskkill.exe" /PID $process.Id /T /F > $null 2> $null
            } else {
                $process.Kill($true)
            }
        } catch {
            try { $process.Kill() } catch { }
        }
        try { $process.StandardOutput.Close() } catch { }
        try { $process.StandardError.Close() } catch { }
        try { [void]$process.WaitForExit(5000) } catch { }
        try { [void]$stdoutTask.Wait(1000) } catch { }
        try { [void]$stderrTask.Wait(1000) } catch { }

        throw "Plugin command timed out after $boundedTimeout seconds: $ScriptPath"
    }

    $process.WaitForExit()
    $stdout = $stdoutTask.GetAwaiter().GetResult()
    $stderr = $stderrTask.GetAwaiter().GetResult()

    if ($stderr.Length -gt 0) {
        [Console]::Error.Write($stderr)
    }

    if ($stdout.Length -gt 0) {
        Write-Output ($stdout.TrimEnd("`r", "`n"))
    }

    if ($process.ExitCode -ne 0) {
        $msg = "Plugin command failed with exit code $($process.ExitCode)."
        if ($stdout) { $msg += "`n" + $stdout }
        throw $msg
    }
}

$pluginRootFull = Resolve-FullPath $PluginRoot

$paramsObjectBound = $PSBoundParameters.ContainsKey('ParamsObject')
if ($paramsObjectBound -and ($PSBoundParameters.ContainsKey('Params') -or $PSBoundParameters.ContainsKey('ParamsPath'))) {
    throw '-ParamsObject cannot be combined with -Params or -ParamsPath.'
}

$paramsFromObject = ''
if ($paramsObjectBound) {
    . (Join-Path $pluginRootFull 'lib\yaml-object-mutation.ps1')
    Import-McpYamlSerializer
    $paramsFromObject = ConvertTo-Yaml -Data $ParamsObject -Options WithIndentedSequences
}

switch ($Command) {
    'Status' {
        Invoke-PowerShellPluginScript -ScriptPath (Join-Path $pluginRootFull 'lib\mcp-status.ps1')
    }
    'Invoke' {
        if (-not $Method) {
            throw '-Method is required when -Command Invoke is used.'
        }

        $paramsText = if ($paramsObjectBound) {
            $paramsFromObject
        } else {
            Read-OptionalText -Inline $Params -HasInline:$($PSBoundParameters.ContainsKey('Params')) -Path $ParamsPath
        }

        Invoke-PowerShellPluginScript -ScriptPath (Join-Path $pluginRootFull 'lib\repl-invoke.ps1') -Arguments @('-Method', $Method, '-ParamsYaml', ($paramsText ?? ''))
    }
    'CompleteTurn' {
        $responseText = Read-OptionalText -Inline $Response -HasInline:$($PSBoundParameters.ContainsKey('Response')) -Path $ResponsePath
        if (-not $responseText) {
            $responseText = 'Turn completed.'
        }

        Invoke-PowerShellPluginScript -ScriptPath (Join-Path $pluginRootFull 'lib\final-response.ps1') -StandardInput $responseText
    }
}

function Invoke-ReplRaw {
    param(
        [Parameter(Mandatory)][string]$Method,
        [string]$ParamsYaml = ''
    )
    if ($script:ReplFailsafeDrainDeferred -and -not $script:ReplRawInFlight) {
        $script:ReplFailsafeDrainDeferred = $false
        Invoke-ReplFailsafeDrainOnFirstSuccessCore
    }
    $script:ReplRawInFlight = $true
    try {
        return (Invoke-ReplRawCore -Method $Method -ParamsYaml $ParamsYaml)
    }
    finally {
        $script:ReplRawInFlight = $false
    }
}

function Invoke-ReplRawCore {
    param(
        [Parameter(Mandatory)][string]$Method,
        [string]$ParamsYaml = ''
    )
    if (-not (Assert-ReplMarkerFresh)) {
        return (New-McpPluginReplResult -Success $false -Output '' -Error 'MCP_UNTRUSTED: marker refresh failed before REPL request')
    }

    $replCommand = Get-Command mcpserver-repl -ErrorAction SilentlyContinue
    $replExe = $null
    if ($env:MCP_REPL_EXECUTABLE -and (Test-Path -LiteralPath $env:MCP_REPL_EXECUTABLE)) {
        $replExe = $env:MCP_REPL_EXECUTABLE
    } elseif ($replCommand) {
        $replExe = [string]$replCommand.Source
    }
    if ([string]::IsNullOrWhiteSpace($replExe)) {
        return (New-McpPluginReplResult -Success $false -Output '' -Error 'mcpserver-repl not found on PATH')
    }

    $requestId = "req-$(Get-Date -AsUTC -Format 'yyyyMMddTHHmmssZ')-$((Get-Random -Maximum 0xFFFF).ToString('x4'))"
    $timeout = Get-ReplMethodTimeoutSeconds -Method $Method

    # Build as an object and serialize to JSON so request envelopes keep a
    # single canonical shape across plugin hosts.
    $paramsObject = $null
    if ($ParamsYaml) {
        $paramsObject = Convert-ReplParamsYamlToObject -ParamsYaml $ParamsYaml
    }
    $request = New-McpPluginReplRequest -RequestId $requestId -Method $Method -Params $paramsObject
    $envelope = ConvertTo-McpPluginJson -InputObject $request -Depth 20 -Compress

    try {
        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        if ($replExe -match '\.(cmd|bat)$') {
            $psi.FileName = $env:ComSpec
            $psi.ArgumentList.Add('/c')
            $psi.ArgumentList.Add($replExe)
        } else {
            $psi.FileName = $replExe
        }
        $psi.ArgumentList.Add('--agent-stdio')
        $psi.ArgumentList.Add('--agent')
        $psi.ArgumentList.Add($script:AgentName)
        $psi.RedirectStandardInput = $true
        $psi.RedirectStandardOutput = $true
        # Do NOT redirect stderr: mcpserver-repl logs verbose 'info:' lines
        # to stderr, and an unread redirected stream blocks the child once
        # its pipe buffer fills (Windows ~4 KB), causing WaitForExit to hang.
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        Set-ReplProcessWorkspace -StartInfo $psi
        # mcpserver-repl writes UTF-8 (with BOM). Without explicit encoding,
        # PowerShell decodes as cp437 and BOM bytes (EF BB BF) become box-
        # drawing glyphs that break the '^type: error' regex anchor.
        $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8

        $proc = [System.Diagnostics.Process]::Start($psi)
        $budget = [System.Diagnostics.Stopwatch]::StartNew()
        $envFile = Join-Path (Get-ReplInvokeCacheDir) "envelope-$requestId.tmp"
        [System.IO.File]::WriteAllText($envFile, $envelope, [System.Text.Encoding]::UTF8)
        $copyStream = [System.IO.File]::OpenRead($envFile)
        $copyTask = $copyStream.CopyToAsync($proc.StandardInput.BaseStream)
        $copyBudget = [int][Math]::Max(1, ($timeout * 1000) - $budget.ElapsedMilliseconds)
        if (-not $copyTask.Wait($copyBudget)) {
            try { $copyStream.Dispose() } catch { }
            try { $proc.Kill($true) } catch { }
            try { [void]$proc.WaitForExit(2000) } catch { }
            Remove-Item $envFile -ErrorAction SilentlyContinue
            return (New-McpPluginReplResult -Success $false -Output '' -Error "mcpserver-repl timed out after ${timeout}s")
        }
        $copyStream.Dispose()
        $proc.StandardInput.Close()
        Remove-Item $envFile -ErrorAction SilentlyContinue

        # Drain stdout BEFORE waiting for exit. With a redirected pipe, the
        # child blocks on stdout writes once the pipe buffer (~4 KB on
        # Windows) fills, and WaitForExit then deadlocks. ReadToEndAsync
        # streams the buffer concurrently and resolves when the child closes
        # stdout (which happens at process exit).
        $readTask = $proc.StandardOutput.ReadToEndAsync()
        $readBudget = [int][Math]::Max(1, ($timeout * 1000) - $budget.ElapsedMilliseconds)
        if (-not $readTask.Wait($readBudget)) {
            try { $proc.Kill($true) } catch { }
            try { [void]$proc.WaitForExit(2000) } catch { }
            return (New-McpPluginReplResult -Success $false -Output '' -Error "mcpserver-repl timed out after ${timeout}s")
        }
        $output = $readTask.Result
        $exitBudget = [int][Math]::Max(1, ($timeout * 1000) - $budget.ElapsedMilliseconds)
        if (-not $proc.WaitForExit($exitBudget)) {
            try { $proc.Kill($true) } catch { }
            try { [void]$proc.WaitForExit(2000) } catch { }
            return (New-McpPluginReplResult -Success $false -Output '' -Error "mcpserver-repl timed out after ${timeout}s")
        }

        # mcpserver-repl writes a UTF-8 BOM before the YAML doc and may
        # interleave logger 'info:' lines on stdout — strip BOM and ignore
        # leading log noise so the regex anchor matches the real header.
        $output = $output -replace "[\uFEFF]", ''
        $isError = $output -match '(?m)^type:\s*error\b'
        if ($proc.ExitCode -ne 0 -or $isError) {
            return (New-McpPluginReplResult -Success $false -Output $output -ExitCode $proc.ExitCode)
        }
        # TR-MCP-REPL-016: this is the first proof in the process that the backend
        # answers, so it is the safe moment to replay anything the failsafe queue
        # captured while it was unreachable. Guarded to run at most once.
        Invoke-ReplFailsafeDrainOnFirstSuccess

